                r#"
extends:
  - url: {}
app_name: MyApp
steps:
  install:
    command: yarn install
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

        let resolver = resolver_for_mock(&server);
        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();

        // Local overrides base
